import { Desktop } from "@wxcc-desktop/sdk"
import { Service } from "@wxcc-desktop/sdk-types";


//Creating a custom logger
const logger = Desktop.logger.createLogger('dtmf-input-logger');

export class DtmfInput extends HTMLElement {
  private input!: HTMLInputElement;
  private container!: HTMLElement;
  private pasteButton!: HTMLButtonElement;
  private submitButton!: HTMLButtonElement;
  private _interactionId: null | string = null;
  private _active = false;

  static get observedAttributes() {
    return ['darkmode'];
  }

  constructor() {
    super();
    const shadow = this.attachShadow({ mode: 'open' });
    shadow.innerHTML = `
      <style>
        :host {
          display: flex;
          width: 100%;
          height: 100%;
          align-items: center;
          justify-content: center;

          --input-bg: rgba(255, 255, 255, 0.6);
          --input-fg: #222;
          --input-border: rgba(0,0,0,0.15);

          --button-bg: #3b82f6;
          --button-fg: white;
          --button-hover: #2563eb;
          --button-success-bg: oklch(62.7% 0.194 149.214);
          --button-success-text: white;

          --icon-bg: rgba(255,255,255,0.6);
          --icon-hover-bg: rgba(255,255,255,0.8);
          --icon-border: rgba(0,0,0,0.15);
        }

        :host(.dark) {
          --input-bg: rgba(255,255,255,0.08);
          --input-fg: #f1f5f9;
          --input-border: rgba(255,255,255,0.18);

          --button-bg: #2563eb;
          --button-fg: #f1f5f9;
          --button-hover: #1d4ed8;
          --button-success-bg: oklch(72.3% 0.219 149.579);

          --icon-bg: rgba(255,255,255,0.06);
          --icon-hover-bg: rgba(255,255,255,0.15);
          --icon-border: rgba(255,255,255,0.2);
        }

        .dtmf-form {
          display: flex;
          align-items: center;
          justify-content: center;
          width: 100%;
          height: 100%;
          box-sizing: border-box;
          gap: 0.25rem;

          transition: opacity 0.3s ease, transform 0.3s ease;
          opacity: 0;
          transform: translateY(-10px);
          pointer-events: none;
        }

        .dtmf-form.active {
          opacity: 1;
          transform: translateY(0);
          pointer-events: auto;
        }

        input {
          height: 32px;
          width: 12ch;
          font-size: 0.9rem;
          padding: 0.35em 0.55em;
          border: 1px solid var(--input-border);
          border-radius: 0.4em;
          outline: none;
          background: var(--input-bg);
          color: var(--input-fg);
          box-sizing: border-box;
          transition: border-color 0.2s, box-shadow 0.2s;
          backdrop-filter: blur(6px);
        }

        input:focus {
          border-color: #3b82f6;
          box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.25);
        }

        .button {
          display: inline-flex;
          align-items: center;
          justify-content: center;
          height: 32px;
          gap: 0.2em;
          padding: 0.4em 0.75em;
          border: none;
          border-radius: 0.4em;
          font-size: 1rem;
          font-weight: 500;
          cursor: pointer;
          transition: all 0.2s ease;
        }

        /* Submit Button - Primary */
        .button--submit {
          background: var(--button-bg);
          color: var(--button-fg);
          font-weight: 500;
          width: 6rem;
        }

        .button--submit:hover {
          background: var(--button-hover);
        }

        .button--success {
          background: var(--button-success-bg);
          color: var(--button-success-text);
        }

        .button--submit.button--success:hover {
          background: var(--button-success-hover);
        }

        .button--submit:disabled {
          cursor: not-allowed;
          pointer-events: none;
        }

        .button--submit:active {
          transform: translateY(1px);
        }

        .button--icon {
          width: 32px;
          height: 32px;
          padding: 0.4em;
          display: inline-flex;
          align-items: center;
          justify-content: center;
          background: var(--icon-bg);
          color: var(--icon-fg);
          border: 1px solid var(--icon-border);
          border-radius: 0.4em;
          aspect-ratio: 1;
          cursor: pointer;
          transition: background 0.2s ease, border-color 0.2s ease;
        }

        .button--icon:hover {
          background: var(--icon-hover-bg);
          border-color: var(--icon-fg);
        }

        .button--icon:active {
          background: var(--icon-hover-bg); /* same as hover for better contrast */
          border-color: var(--icon-fg);
        }


        .button__icon {
          height: 100%;
          width: 100%;
          fill: currentColor;
        }

        /* Dark mode input focus glow */
        :host(.dark) input:focus {
          box-shadow: 0 0 0 3px rgba(96, 165, 250, 0.3);
        }
      </style>

      <div class="dtmf-form">
        <button type="button" class="button button--icon" data-role="paste" title="Paste from clipboard" aria-label="Paste from clipboard">
          <svg xmlns="http://www.w3.org/2000/svg" class="button__icon" viewBox="0 -960 960 960">
            <path d="m720-120-56-57 63-63H480v-80h247l-63-64 56-56 160 160-160 160Zm120-400h-80v-240h-80v120H280v-120h-80v560h200v80H200q-33 0-56.5-23.5T120-200v-560q0-33 23.5-56.5T200-840h167q11-35 43-57.5t70-22.5q40 0 71.5 22.5T594-840h166q33 0 56.5 23.5T840-760v240ZM480-760q17 0 28.5-11.5T520-800q0-17-11.5-28.5T480-840q-17 0-28.5 11.5T440-800q0 17 11.5 28.5T480-760Z" />
          </svg>
        </button>
        <input type="text" placeholder="Enter DTMF" maxlength="10" aria-label="DTMF Input" />
        <button type="button" class="button button--submit" title="Submit DTMF" aria-label="Submit DTMF">Submit</button>
      </div>
    `;
  }

  connectedCallback() {
    Desktop.config.init({ widgetName: "DTMF Input", widgetProvider: "Conscia Ireland" });
    this.container = this.shadowRoot!.querySelector('.dtmf-form')!;
    this.input = this.shadowRoot!.querySelector('input')!;
    this.submitButton = this.shadowRoot!.querySelector('.button--submit')!;
    this.pasteButton = this.shadowRoot!.querySelector('[data-role="paste"]')!;

    // Paste from clipboard
    this.pasteButton.addEventListener("click", async () => {
      if (!navigator.clipboard?.readText) {
        alert("Clipboard access not supported. Please paste manually.");
        return;
      }

      try {
        const text = await navigator.clipboard.readText();
        const filtered = text.replace(/[^0-9*#]/g, '');
        this.input.value = filtered;
        this.input.dispatchEvent(new Event('input'));
        this.input.focus();
      } catch (err) {
        logger.warn("Clipboard error:", err);
        alert("Failed to paste. Try Ctrl+V.");
      }
    });

    // Filter input in real-time
    this.input.addEventListener("input", () => {
      const filtered = this.input.value.replace(/[^0-9*#]/g, '');
      if (this.input.value !== filtered) {
        this.input.value = filtered;
      }
    });

    this.input.addEventListener("keydown", (e) => {
      if (e.key === "Enter") {
        e.preventDefault();
        this.sendDtmf();
      }
    });

    this.submitButton.addEventListener("click", () => {
      this.sendDtmf();
    });

    this.webexEventListeners();
  }

  private sendDtmf() {
    const value = this.input.value.trim();

    if (!value) {
      return;
    }

    this.submitButton.disabled = true;
    this.submitButton.classList.add("button--success");

    this.submitButton.innerHTML = `
    <span>Sent</span>
    <svg xmlns="http://www.w3.org/2000/svg"
         height="20px"
         viewBox="0 -960 960 960"
         width="20px"
         class="button__icon">
      <path d="M382-240 154-468l57-57 171 171 367-367 57 57-424 424Z"
            fill="currentColor" />
    </svg>
  `;

    logger.info("sending DTMF values", value);

    Desktop.agentContact.sendDtmf(value);

    setTimeout(() => {
      this.submitButton.disabled = false;
      this.submitButton.classList.remove("button--success");
      this.submitButton.textContent = "Submit";
    }, 2000);

    this.input.value = '';
  }


  disconnectedCallback() {
    logger.info("Widget disconnected. Removing listeners..");
    Desktop.agentContact.removeAllEventListeners();
  }

  public get active() {
    return this._active;
  }

  show() {
    this._active = true;
    this.container.classList.add('active');
    this.input.focus();
  }

  hide() {
    this._active = false;
    this.container.classList.remove('active');
  }


  webexEventListeners() {
    Desktop.agentContact.addEventListener("eAgentContactAssigned", (message: Service.Aqm.Contact.AgentContact) => {
      //logger.info('eAgentContactAssigned', JSON.stringify(message));
      logger.info("eAgentContactAssigned");
      logger.info("media type is:", message.data.interaction.mediaType);
      logger.info("interactionId", message.data.interaction.interactionId);
      if (message.data.interaction.mediaType === "telephony" && !this._interactionId) {
        this._interactionId = message.data.interactionId;
        this.show();
        logger.info("New voice interaction. Showing the widget");
      }
    });

    Desktop.agentContact.addEventListener("eAgentContactWrappedUp", (message: Service.Aqm.Contact.AgentContact) => {
      logger.info("eAgentContactWrappedUp")
      logger.info("media type is:", message.data.interaction.mediaType);
      logger.info("interactionId", message.data.interaction.interactionId);
      if (message.data.interactionId === this._interactionId) {
        this._interactionId = null;
        this.hide();
        logger.info("Tracked interaction closed. Hiding the widget");
      }
    });
  }

  // Handle darkmode="true" | "false"
  attributeChangedCallback(name: string, _: string, newValue: string) {
    if (name === 'darkmode') {
      const isDark = newValue === 'true';
      if (isDark) {
        this.classList.add('dark');
      } else {
        this.classList.remove('dark');
      }
    }
  }
}

customElements.define('dtmf-input', DtmfInput);
